//! Case c17: generates `$OUT_DIR/generated.rs`, which is `include!`d by
//! `app::cases::c17_build_rs::generated`. The generated fn calls into
//! `app::gen_target`.

use std::{env, fs, path::Path};

fn main() {
    let out_dir = env::var("OUT_DIR").expect("OUT_DIR set by cargo");
    let code = "\
/// Generated by build.rs. Calls into `crate::gen_target`.
pub fn generated_entry() -> u32 {
    crate::gen_target::target_fn() + 1
}
";
    fs::write(Path::new(&out_dir).join("generated.rs"), code).expect("write generated.rs");
    println!("cargo::rerun-if-changed=build.rs");
}
